import java.util.Scanner;

public class Main {
    private static final int DISCOUNT_QUANTITY = 10;
    private static final double DISCOUNT_RATE = 0.10;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String item = scanner.nextLine();
        int quantity = scanner.nextInt();
        double unitPrice = scanner.nextDouble();
        double rate = quantity >= DISCOUNT_QUANTITY ? DISCOUNT_RATE : 0.0;
        double total = calculateTotal(unitPrice, quantity, rate);
        StringBuilder receipt = new StringBuilder();
        receipt.append("Item: ").append(item).append('\n');
        receipt.append("Quantity: ").append(quantity).append('\n');
        receipt.append("Total: €").append(String.format("%.2f", total));
        System.out.println(receipt.toString());
    }

    public static double calculateTotal(double unitPrice, int quantity, double discountRate) {
        double subtotal = unitPrice * quantity;
        return subtotal * (1.0 - discountRate);
    }
}

