            if (answer == correct) {
                System.out.println("Correct");
                score++;
            } else {
                System.out.println("Incorrect: " + correct);
            }
        }
        System.out.println("Score: " + score + "/3");
    }

    public static int add(int a, int b) {
        return a + b;
    }
